import { algoliasearch } from 'algoliasearch/lite';

const client = algoliasearch('OSJISXEYU4', '7b29281d589f9f5e2b597c36e288d713'); // Reemplaza con tus credenciales
const index = client.initIndex('pet'); // Reemplaza con el nombre de tu índice

export default index;
